#include "../voxelization-cuda/kernels.h"
#include <fstream>
#include <chrono>
#include <stdexcept>
#include <string>
using U=unsigned;constexpr int G=64;constexpr U GUARD=0xdeadbeef;
void ck(cudaError_t e){if(e!=cudaSuccess)throw std::runtime_error(cudaGetErrorString(e));}
struct Buffer{U*p;size_t n;};
Buffer alloc(size_t n){U*p;ck(cudaMalloc(&p,(n+128)*4));std::vector<U>h(n+128,GUARD);ck(cudaMemcpy(p,h.data(),h.size()*4,cudaMemcpyHostToDevice));return{p,n};}
std::vector<U>readwords(const char*name){std::ifstream f(std::string(VOX_ROOT)+"/"+name,std::ios::binary|std::ios::ate);if(!f)throw std::runtime_error("missing fixture");size_t z=f.tellg();if(z%4)throw std::runtime_error("fixture size");std::vector<U>v(z/4);f.seekg(0);f.read((char*)v.data(),z);if(!f)throw std::runtime_error("fixture read");return v;}
struct Case{int n;std::vector<Buffer>b;};
void reset(Case&c){int vals[]={0,255,0,255,0,0,0};for(int j=1;j<7;j++)ck(cudaMemset(c.b[j].p+G,vals[j],c.b[j].n*4));ck(cudaDeviceSynchronize());}
void first(Case&c){auto&b=c.b;ck(voxelizationLaunch((float*)(b[0].p+G),c.n,params_.min_x_range,params_.max_x_range,params_.min_y_range,params_.max_y_range,params_.min_z_range,params_.max_z_range,params_.pillar_x_size,params_.pillar_y_size,params_.pillar_z_size,params_.getGridXSize(),params_.getGridYSize(),params_.getGridZSize(),params_.feature_num,params_.max_voxels,params_.max_points_per_voxel,b[1].p+G,b[2].p+G,(float*)(b[3].p+G),b[4].p+G,b[5].p+G));ck(cudaDeviceSynchronize());}
int realcount(Case&c){U real;ck(cudaMemcpy(&real,c.b[5].p+G,4,cudaMemcpyDeviceToHost));if(!real||real%256)throw std::runtime_error("sourcefullfeaturegridcontrol");return real;}
void second(Case&c,U real){auto&b=c.b;ck(featureExtractionLaunch((float*)(b[3].p+G),b[2].p+G,&real,params_.max_points_per_voxel,params_.feature_num,(half*)(b[6].p+G)));ck(cudaDeviceSynchronize());}
void dump(std::ofstream&f,Buffer b){std::vector<U>v(b.n+128);ck(cudaMemcpy(v.data(),b.p,v.size()*4,cudaMemcpyDeviceToHost));f.write((char*)v.data(),v.size()*4);if(!f)throw std::runtime_error("raw write");}
int main(){try{auto data=readwords("fixtures_u32.bin");size_t idx=1;std::vector<Case>cases;for(int ci=0;ci<4;ci++){Case c;c.n=data[idx++];size_t sizes[]={size_t(5*c.n),1200000,160000,8000000,640000,1,4000000};for(auto n:sizes)c.b.push_back(alloc(n));ck(cudaMemcpy(c.b[0].p+G,data.data()+idx,c.n*20,cudaMemcpyHostToDevice));idx+=5*c.n;cases.push_back(c);}if(idx!=data.size())throw std::runtime_error("fixture parse");for(auto&c:cases){reset(c);first(c);second(c,realcount(c));}for(int trial=1;trial<=5;trial++){std::string raw="raw_trial_"+std::to_string(trial)+".bin",out="trial_"+std::to_string(trial)+".bin";std::ofstream f(raw,std::ios::binary);U count=4;f.write((char*)&count,4);std::vector<double>times;for(auto&c:cases){reset(c);auto a=std::chrono::steady_clock::now();first(c);auto z=std::chrono::steady_clock::now();times.push_back(std::chrono::duration<double>(z-a).count());U real=realcount(c);U n=c.n;f.write((char*)&n,4);for(int j=0;j<6;j++)dump(f,c.b[j]);a=std::chrono::steady_clock::now();second(c,real);z=std::chrono::steady_clock::now();times.push_back(std::chrono::duration<double>(z-a).count());for(int j:{2,3,6})dump(f,c.b[j]);}f.close();std::string cmd="python3 \""+std::string(VOX_ROOT)+"/study_capture.py\" "+raw+" "+out+" cuda "+std::to_string(trial);if(std::system(cmd.c_str())!=0)throw std::runtime_error("independent fullcapture rejected");std::ifstream ix(out+".index");std::string index;std::getline(ix,index);double total=0;for(auto x:times)total+=x;std::cout.precision(17);std::cout<<"STUDY_TRIAL {\"trial\":"<<trial<<",\"time_seconds\":"<<total<<",\"correct\":true,\"checked_values\":113497,\"max_abs_error\":0,\"max_rel_error\":null,\"timing_region\":\"sum4_completed_hash_scatter_plus_completed_feature_kernels\",\"jit_excluded\":true,\"internal_repeats\":1,\"timed_kernel_calls\":12,\"raw_output_identity_claim\":false,\"raw_state_index\":\""<<index<<"\",\"stage_times_seconds\":[";for(int i=0;i<8;i++)std::cout<<(i?",":"")<<times[i];std::cout<<"],\"output_artifact\":{\"path\":\""<<out<<"\",\"dtype\":\"uint32\",\"count\":113497,\"byte_order\":\"little\"}}\n";}for(auto&c:cases)for(auto b:c.b)ck(cudaFree(b.p));return 0;}catch(std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
